edits.replacement:
#root #keyslist .keybtn.wait{ box-shadow:none; }
/* v31.xx (cw-pset7) critic c-31z round 2 (Pad buttons 74 at 2, P0: "every action label starts with a capital letter ... his order is all lower case"; P1: "the 3px bottom bevel is a shadow-style edge the guide bans"; "the last line is hard-clipped at the footer"). Now: the Keys and Pad buttons rows show their words as written (lower case, the ::first-letter capital is gone), key caps are a flat 1px line box with no bevel, and the list keeps 32px under its last row. */
#root #keyslist .row b::first-letter{ text-transform:none; }
#root #keyslist .keybtn{ box-shadow:none; }
#root #keyslist{ padding-bottom:var(--sp-4); }

check:
{v:'VER',what:'the Keys list shows lower case words: no first-letter capital, and key caps have no bevel',
 run:function(){
   var bad=[], b, k, cs, padWas=document.body.classList.contains('padon');
   __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
   try{
     document.body.classList.remove('padon');
     keysOpen(false);
     b=document.querySelector('#keyslist .row b'); k=document.querySelector('#keyslist .keybtn');
     if(!b) bad.push('no key row');
     else{ cs=getComputedStyle(b,'::first-letter'); if(cs.textTransform==='uppercase') bad.push('the first letter of a key action is still upper case'); }
     if(k && getComputedStyle(k).boxShadow!=='none') bad.push('the key cap still has a bevel: '+getComputedStyle(k).boxShadow);
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ var q=document.getElementById('keysmodal'); if(q) q.classList.remove('on'); }catch(_k){} try{ __topClear(); }catch(_c){} document.body.classList.toggle('padon',padWas); }
   return bad.length?bad.join('; '):null; }},
